l feeRounded2 = rawFee.setScale(2, RM);\n                    if (feeRounded2.compareTo(fr.min2) < 0) feeRounded2 = fr.min2;\n                    if (feeRounded2.compareTo(fr.max2) > 0) feeRounded2 = fr.max2;\n                    fee2 = feeRounded2.setScale(2, RM);\n                }\n            }\n\n            BigDecimal adjusted2 = amountAcct10.setScale(2, RM).subtract(fee2).setScale(2, RM);\n\n            BigDecimal prev = adjustedSumByAccount.get(a.accountId);\n            if (prev == null) prev = BD_0.setScale(2, RM);\n            adjustedSumByAccount.put(a.accountId, prev.add(adjusted2).setScale(2, RM));\n\n            validTxs++;\n        }\n\n        // Compute per-account interest lines\n        List<String> accountIds = new ArrayList<String>(accounts.keySet());\n        Collections.sort(accountIds);\n\n        class InterestLine {\n            String accountId;\n            String bizDate;\n            BigDecimal eod2;\n            BigDecimal apr6;\n            BigDecimal dailyInterestRaw10;\n            BigDecimal dailyInterest2;\n        }\n\n        List<InterestLine> lines = new ArrayList<InterestLine>();\n        BigDecimal totalInterestRaw10 = BD_0.setScale(10, RM);\n\n        for (int i = 0; i < accountIds.size(); i++) {\n            String aid = accountIds.get(i);\n            Account a = accounts.get(aid);\n            BigDecimal sumAdj2 = adjustedSumByAccount.get(aid);\n            if (sumAdj2 == null) sumAdj2 = BD_0.setScale(2, RM);\n\n            BigDecimal eod2 = a.startBalance2.add(sumAdj2).setScale(2, RM);\n\n            int daysSinceOpened = bizEpochDay - a.openedEpochDay;\n            boolean promo = (a.promoDays > 0) && (daysSinceOpened < a.promoDays);\n            boolean tier = eod2.compareTo(a.tierThreshold2) >= 0;\n\n            BigDecimal apr = a.baseApr;\n            if (tier) apr = apr.add(a.tierApr);\n            if (promo) apr = apr.add(a.promoApr);\n            BigDecimal apr6 = apr.setScale(6, RM);\n\n            BigDecimal pr